import type { GrowthField, GrowthTool } from './growth-tools';

type NumericField = [key: string, label: string, value: string, min?: number, max?: number, step?: string];
type ToolSpec = {
  slug: string;
  title: string;
  description: string;
  kind?: 'design' | 'text';
  inputLabel?: string;
  reference?: string;
  action: string;
  fields: NumericField[];
  formula: string;
  limits: string;
  faq: string;
  select?: { key: string; label: string; value: string; options: { value: string; label: string }[] };
  selects?: { key: string; label: string; value: string; options: { value: string; label: string }[] }[];
  textFields?: [key: string, label: string, value: string, type?: 'date' | 'text'][];
};

const specs: ToolSpec[] = [
  { slug: 'paint-calculator', title: 'Paint Calculator', description: 'Estimate how many litres of paint you need from wall area, number of coats, coverage and a waste allowance.', action: 'Estimate paint', fields: [['area','Wall area (m²)','40',0.01,100000],['coats','Number of coats','2',1,10,'1'],['coverage','Paint coverage (m² per litre)','10',0.01,1000],['waste','Extra allowance (%)','10',0,100]], formula: 'Paint litres = wall area × coats × (1 + allowance) ÷ stated coverage per litre. Round up to practical whole-litre cans.', limits: 'Enter the total paintable wall area in square metres. Subtract large openings yourself and check the coverage printed on the paint can; textured surfaces can use more paint.', faq: 'How much paint do I need for two coats? Add the wall areas, multiply by two, then divide by the coverage per litre. This estimate adds your selected allowance and rounds up.' },
  { slug: 'flooring-calculator', title: 'Flooring Calculator', description: 'Calculate floor area, add a cutting allowance and estimate how many flooring packs to buy.', action: 'Calculate flooring', fields: [['length','Room length (m)','5',0.01,10000],['width','Room width (m)','4',0.01,10000],['packArea','Coverage per pack (m²)','2.2',0.01,1000],['waste','Cutting allowance (%)','10',0,100]], formula: 'Floor area = length × width. Required packs = area × (1 + cutting allowance) ÷ coverage per pack, rounded up.', limits: 'Measure each room at floor level and calculate irregular rooms as separate rectangles. Pack coverage can vary by product, so use the value on the packaging.', faq: 'How much extra flooring should I order? The default 10% allowance covers many straightforward rooms, but angled layouts and complex cuts may need more.' },
  { slug: 'tile-calculator', title: 'Tile Calculator', description: 'Estimate tile quantity from room dimensions, tile size and a cutting allowance before a renovation.', action: 'Calculate tiles', fields: [['length','Area length (m)','3',0.01,10000],['width','Area width (m)','2',0.01,10000],['tileLength','Tile length (cm)','30',1,500],['tileWidth','Tile width (cm)','30',1,500],['waste','Extra tiles (%)','10',0,100]], formula: 'Tile count = floor area ÷ one tile area, multiplied by the cutting allowance and rounded up to a whole tile.', limits: 'This is an area estimate and does not model grout lines, patterns, borders, broken tiles or separate wall and floor layouts. Buy matching tiles from the same batch when possible.', faq: 'How many spare tiles should I buy? A 10% spare allowance is a common starting point for simple layouts. Add more for diagonal patterns, many corners or future repairs.' },
  { slug: 'concrete-calculator', title: 'Concrete Calculator', description: 'Estimate concrete volume and bag count for a slab using length, width, depth and bag yield.', action: 'Estimate concrete', fields: [['length','Slab length (m)','3',0.01,10000],['width','Slab width (m)','2',0.01,10000],['depth','Slab depth (cm)','10',0.1,1000],['yield','Yield per bag (litres)','20',0.1,1000]], formula: 'Volume in cubic metres = length × width × depth in metres. Bag count = volume in litres ÷ stated bag yield, rounded up.', limits: 'The result excludes ground preparation, reinforcement, spillage and uneven excavation. Concrete mixes have different yields; check the product bag and consult local building requirements for structural work.', faq: 'How many bags of concrete do I need for a slab? Convert the slab dimensions to metres, multiply them for volume, convert cubic metres to litres and divide by the bag yield.' },
  { slug: 'mulch-calculator', title: 'Mulch Calculator', description: 'Work out mulch volume and the number of bags for a garden bed based on area and depth.', action: 'Calculate mulch', fields: [['area','Garden bed area (m²)','12',0.01,100000],['depth','Mulch depth (cm)','5',0.1,100],['bag','Bag size (litres)','50',1,2000]], formula: 'Volume in litres = bed area × depth in centimetres × 10. Divide by bag size and round up to full bags.', limits: 'Use the depth recommended for your mulch type and plants. Keep mulch clear of stems and building siding; this estimate does not account for settling or irregular bed edges.', faq: 'How deep should mulch be? Depth depends on the material and planting situation. Enter the depth you plan to apply rather than treating this calculator as a gardening prescription.' },
  { slug: 'garden-soil-calculator', title: 'Garden Soil Calculator', description: 'Estimate soil volume and bags for raised beds or planters from their dimensions and fill depth.', action: 'Calculate soil', fields: [['length','Bed length (m)','2',0.01,10000],['width','Bed width (m)','1',0.01,10000],['depth','Fill depth (cm)','30',0.1,1000],['bag','Bag size (litres)','40',1,2000]], formula: 'Soil volume in litres = length × width × depth in centimetres × 10. Divide by bag volume and round up.', limits: 'For multiple beds, add their areas or calculate each separately. Soil settles and bag volumes are nominal, so consider a small extra amount for topping up.', faq: 'How many litres of soil fit in a raised bed? Multiply the inside length and width in metres by fill depth in centimetres, then multiply by ten.' },
  { slug: 'wallpaper-calculator', title: 'Wallpaper Calculator', description: 'Estimate wallpaper rolls from wall width, wall height, roll size and pattern repeat.', action: 'Estimate wallpaper rolls', fields: [['wallWidth','Total wall width (m)','12',0.01,10000],['wallHeight','Wall height (m)','2.5',0.01,1000],['rollWidth','Roll width (cm)','53',1,500],['rollLength','Roll length (m)','10',0.1,1000],['repeat','Pattern repeat (cm)','0',0,500]], formula: 'Drops = total wall width ÷ roll width, rounded up. Usable drop length includes the wall height plus pattern repeat; rolls are rounded up by drops per roll.', limits: 'This estimate assumes continuous walls and one roll size. Door and window deductions are omitted because pattern matching and offcuts can offset the saved area. Follow the manufacturer’s instructions.', faq: 'Why does wallpaper pattern repeat matter? A larger repeat can create more offcut at the top of each drop, reducing how many full-height drops fit in a roll.' },
  { slug: 'fence-post-calculator', title: 'Fence Post Calculator', description: 'Estimate fence post count from fence length and post spacing, including posts at both ends.', action: 'Calculate posts', fields: [['length','Fence length (m)','30',0.1,100000],['spacing','Maximum post spacing (m)','2.4',0.1,20]], formula: 'Number of spaces = fence length ÷ maximum spacing, rounded up. Add one post for the far end.', limits: 'Corners, gates, slope changes and local wind or soil requirements can require additional posts and closer spacing. Confirm the layout before purchasing materials.', faq: 'How many fence posts do I need? Divide the fence run by your chosen maximum spacing, round up to whole sections and add one post for the final end.' },
  { slug: 'gravel-calculator', title: 'Gravel Calculator', description: 'Estimate gravel volume and approximate tonnes from the area, depth and bulk density.', action: 'Estimate gravel', fields: [['area','Area (m²)','20',0.01,100000],['depth','Depth (cm)','5',0.1,1000],['density','Bulk density (kg/m³)','1700',1,10000]], formula: 'Volume = area × depth in metres. Approximate mass = volume × the bulk density you enter.', limits: 'Gravel density varies with rock type, grading, moisture and compaction. Ask your supplier for the product density and how it is sold before ordering by weight.', faq: 'How much gravel covers 20 square metres? Multiply the area by the intended depth in metres to get cubic metres, then multiply by the supplier’s density for an approximate weight.' },
  { slug: 'deck-board-calculator', title: 'Deck Board Calculator', description: 'Estimate deck board count and total linear metres from deck dimensions, board width, gap and board length.', action: 'Calculate deck boards', fields: [['length','Deck length (m)','5',0.1,10000],['width','Deck width (m)','4',0.1,10000],['boardWidth','Board face width (cm)','14',1,100],['gap','Board gap (mm)','5',0,50],['boardLength','Stock board length (m)','3.6',0.1,1000],['waste','Cutting allowance (%)','10',0,100]], formula: 'Board rows = deck width ÷ board face width plus gap, rounded up. Total linear metres = rows × deck length with the selected allowance; stock boards are rounded up.', limits: 'This estimate assumes parallel boards spanning the deck length. It omits joists, picture framing, stairs, fasteners, structural design and unusable offcuts; verify the framing plan separately.', faq: 'How many deck boards do I need? Estimate the number of rows across the deck, multiply by the deck length and divide the total by your stock board length.' },
  { slug: 'fuel-cost-calculator', title: 'Fuel Cost Calculator', description: 'Estimate trip fuel use and cost from distance, vehicle consumption and fuel price.', action: 'Calculate trip cost', fields: [['distance','Trip distance (km)','250',0.1,10000000],['consumption','Fuel consumption (L/100 km)','7.5',0.01,1000],['price','Fuel price per litre','1.65',0,1000000]], formula: 'Fuel used = distance × consumption ÷ 100. Trip fuel cost = litres used × price per litre.', limits: 'This is a route estimate, not a live fuel quote. Traffic, speed, weather, load, terrain and fuel-price changes affect the actual amount.', faq: 'How do I calculate fuel cost for a trip? Multiply distance by the vehicle’s litres per 100 kilometres, divide by 100 and multiply by the price per litre.' },
  { slug: 'electricity-cost-calculator', title: 'Electricity Cost Calculator', description: 'Estimate the monthly electricity cost of an appliance from watts, daily hours and your price per kWh.', action: 'Estimate electricity cost', fields: [['watts','Appliance power (watts)','1000',0.1,1000000],['hours','Hours used per day','3',0,24],['days','Days used per month','30',0,31,'1'],['price','Electricity price per kWh','0.25',0,1000000]], formula: 'Energy in kWh = watts ÷ 1,000 × hours per day × days. Estimated cost = kWh × price per kWh.', limits: 'Use the appliance’s average power draw when available. Standby use, variable loads, taxes, fixed charges and tiered utility pricing are not included.', faq: 'How much does a 1,000-watt appliance cost to run? One hour uses about 1 kWh. Multiply the hours used by your utility price per kWh.' },
  { slug: 'sales-tax-calculator', title: 'Sales Tax Calculator', description: 'Add sales tax to a price or break the tax amount out of a tax-inclusive total.', action: 'Calculate sales tax', fields: [['amount','Price amount','100',0,1000000000],['rate','Sales tax rate (%)','8.25',0,100]], select: { key: 'mode', label: 'Price includes tax?', value: 'before', options: [{ value: 'before', label: 'No — add tax to this price' }, { value: 'included', label: 'Yes — find tax in this total' }] }, formula: 'For a pre-tax price, tax = amount × rate and total = amount + tax. For a tax-inclusive total, pre-tax amount = total ÷ (1 + rate) and tax is the difference.', limits: 'The calculator handles one flat rate. Tax rules, exemptions, rounding and combined local rates vary by location; confirm the applicable rate with your tax authority.', faq: 'How do I remove sales tax from a total? Divide the tax-inclusive amount by one plus the tax rate as a decimal. Subtract that pre-tax amount from the total to find tax paid.' },
  { slug: 'bill-split-calculator', title: 'Bill Split Calculator', description: 'Split a restaurant or group bill evenly and add an optional tip percentage.', action: 'Split the bill', fields: [['bill','Bill before tip','86.50',0,1000000000],['people','Number of people','4',1,10000,'1'],['tip','Tip (%)','18',0,100]], formula: 'Tip = bill × tip percentage. Per-person amount = (bill + tip) ÷ number of people.', limits: 'The result is rounded to two decimal places per person. If the rounded shares do not add back to the exact total, one person may need to cover the remaining cent(s).', faq: 'How do you split a bill with tip? Calculate the tip from the bill, add it to the total and divide the result by the number of people.' },
  { slug: 'salary-to-hourly-calculator', title: 'Salary to Hourly Calculator', description: 'Convert annual salary into estimated hourly, weekly and monthly pay using your work schedule.', action: 'Convert salary', fields: [['salary','Annual salary','52000',0,1000000000],['hours','Hours per week','40',0.1,168],['weeks','Paid work weeks per year','52',0.1,53]], formula: 'Hourly equivalent = annual salary ÷ (hours per week × paid weeks). Weekly and monthly equivalents divide the annual salary by 52 and 12.', limits: 'These are gross-pay equivalents before tax, benefits, overtime or unpaid leave. Bonuses and variable schedules are not included unless you add them to annual salary.', faq: 'How much is a yearly salary per hour? Divide annual gross salary by your weekly hours multiplied by the number of paid work weeks in the year.' },
  { slug: 'overtime-pay-calculator', title: 'Overtime Pay Calculator', description: 'Estimate gross weekly pay with a regular-hours threshold and an overtime pay multiplier.', action: 'Calculate gross pay', fields: [['hours','Hours worked this week','45',0,168],['rate','Hourly pay rate','20',0,1000000],['threshold','Regular hours threshold','40',0,168],['multiplier','Overtime multiplier','1.5',0,10]], formula: 'Regular pay uses hours up to the threshold. Remaining hours are multiplied by the hourly rate and overtime multiplier.', limits: 'This is a simple gross-pay estimate and does not determine legal overtime eligibility, daily overtime, double time, deductions, premiums or local labor-law rules.', faq: 'How is overtime pay estimated? In this calculator, hours above the entered threshold are paid at the hourly rate times the multiplier you provide.' },
  { slug: 'pay-raise-calculator', title: 'Pay Raise Calculator', description: 'Calculate your new salary and increase after a percentage raise, with equivalent monthly and weekly pay.', action: 'Calculate new pay', fields: [['salary','Current annual salary','50000',0,1000000000],['raise','Raise percentage','5',-100,10000]], formula: 'Raise amount = current salary × raise percentage. New salary = current salary + raise amount.', limits: 'This compares gross annual figures before tax, benefits, inflation or changes to working hours. Enter a negative percentage to estimate a pay cut.', faq: 'What is a 5% raise on a salary? Multiply the current salary by 0.05 to get the increase, then add it to the current salary.' },
  { slug: 'savings-goal-calculator', title: 'Savings Goal Calculator', description: 'Estimate how many months it will take to reach a savings target from your current balance and monthly deposit.', action: 'Estimate savings timeline', fields: [['target','Savings goal','10000',0.01,1000000000000],['current','Current savings','1000',0,1000000000000],['monthly','Monthly contribution','300',0.01,1000000000000]], formula: 'Months remaining = the amount still needed divided by the monthly contribution, rounded up to a whole month.', limits: 'This estimate assumes the same deposit every month and no interest, fees, withdrawals or changes in prices. It is a planning aid, not a financial projection.', faq: 'How long will it take to save a goal amount? Subtract current savings from your target and divide the remaining amount by your regular contribution.' },
  { slug: 'grade-needed-calculator', title: 'Grade Needed on Final Calculator', description: 'Find the score needed on a final exam to reach a target course grade based on your current grade and exam weight.', action: 'Find required exam score', fields: [['current','Current course grade (%)','82',0,100],['target','Target final grade (%)','85',0,100],['weight','Final exam weight (%)','30',0.01,100]], formula: 'Required exam score = (target course grade − current grade × (1 − exam weight)) ÷ exam weight.', limits: 'Enter percentages on a 0–100 scale. The result assumes the current grade represents all coursework outside the final and that the entered exam weight is correct.', faq: 'What score do I need on my final? Account for the portion of your course grade already earned, then solve for the exam score using the exam’s share of the final grade.' },
  { slug: 'bmi-calculator', title: 'BMI Calculator', description: 'Calculate body mass index from height and weight using metric units, with the standard adult category ranges.', action: 'Calculate BMI', fields: [['weight','Weight (kg)','70',1,1000],['height','Height (cm)','175',50,300]], formula: 'BMI = weight in kilograms ÷ height in metres squared. Adult screening ranges are shown as general reference values.', limits: 'BMI is a screening measure, not a diagnosis. It does not distinguish muscle from fat and is not intended for children, pregnancy or individual medical decisions. Ask a health professional about personal results.', faq: 'What is a healthy BMI? Standard adult BMI categories range from underweight below 18.5, healthy weight 18.5–24.9, overweight 25–29.9 and obesity 30 or above. BMI alone cannot assess health.' },
  { slug:'cooking-measurement-converter',title:'Cooking Measurement Converter',description:'Convert cups, tablespoons, teaspoons, millilitres, grams and ounces for common baking and cooking ingredients.',action:'Convert cooking measure',fields:[['amount','Amount','1',0.001,100000]],selects:[{key:'ingredient',label:'Ingredient',value:'flour',options:[{value:'flour',label:'All-purpose flour'},{value:'sugar',label:'Granulated sugar'},{value:'brown-sugar',label:'Packed brown sugar'},{value:'butter',label:'Butter'},{value:'water',label:'Water'},{value:'milk',label:'Milk'},{value:'oil',label:'Vegetable oil'},{value:'honey',label:'Honey'},{value:'rice',label:'Uncooked rice'},{value:'oats',label:'Rolled oats'}]},{key:'from','label':'From',value:'cup',options:[{value:'cup',label:'US cup'},{value:'tbsp',label:'Tablespoon'},{value:'tsp',label:'Teaspoon'},{value:'ml',label:'Millilitre'},{value:'g',label:'Gram'},{value:'oz',label:'Ounce'}]},{key:'to',label:'To',value:'g',options:[{value:'cup',label:'US cup'},{value:'tbsp',label:'Tablespoon'},{value:'tsp',label:'Teaspoon'},{value:'ml',label:'Millilitre'},{value:'g',label:'Gram'},{value:'oz',label:'Ounce'}]}],formula:'US volume units convert to millilitres; ingredient-specific approximate density converts volume to grams. Weight units convert using 28.3495 grams per ounce.',limits:'Cup-to-gram values vary by how an ingredient is packed and measured. This tool uses approximate ingredient densities for kitchen estimates; weigh ingredients for precision baking.',faq:'How many grams are in a cup of flour? A US cup of all-purpose flour is roughly 120 grams, but scooping and packing change the actual weight.'},
  { slug:'oven-temperature-converter',title:'Oven Temperature Converter',description:'Convert oven temperatures between Celsius, Fahrenheit and gas mark for recipes from different countries.',action:'Convert oven temperature',fields:[['temperature','Temperature','180',-500,2000]],selects:[{key:'from',label:'Temperature unit',value:'c',options:[{value:'c',label:'Celsius'},{value:'f',label:'Fahrenheit'},{value:'gas',label:'Gas mark'}]}],formula:'Fahrenheit = Celsius × 9 ÷ 5 + 32. Gas marks are approximate conventional oven settings mapped to Celsius ranges.',limits:'Gas marks and fan oven adjustments are approximate. Follow the recipe and appliance manual when exact temperature matters.',faq:'What is 180°C in Fahrenheit? 180°C is 356°F, commonly rounded to 350°F in many recipes.'},
  { slug:'fuel-economy-converter',title:'Fuel Economy Converter',description:'Convert fuel economy between MPG, US MPG, UK MPG, kilometres per litre and litres per 100 kilometres.',action:'Convert fuel economy',fields:[['value','Fuel economy value','7.5',0.001,100000]],selects:[{key:'from',label:'Convert from',value:'l100',options:[{value:'l100',label:'L/100 km'},{value:'usmpg',label:'US MPG'},{value:'ukmpg',label:'UK MPG'},{value:'kml',label:'km/L'}]}],formula:'All values convert through litres per 100 kilometres; US and UK gallons use different exact litre volumes.',limits:'Vehicle dashboard readings are estimates and real-world economy changes with driving, weather, load and maintenance. US MPG and UK MPG are not interchangeable.',faq:'How do I convert US MPG to L/100 km? Divide 235.215 by US miles per gallon.'},
  { slug:'running-pace-calculator',title:'Running Pace Calculator',description:'Calculate running pace per kilometre and mile, speed and estimated finish time from distance and elapsed time.',action:'Calculate running pace',fields:[['distance','Distance (km)','5',0.01,100000],['hours','Hours','0',0,10000,'1'],['minutes','Minutes','30',0,59,'1'],['seconds','Seconds','0',0,59,'1']],formula:'Pace is elapsed time divided by distance. Speed is distance divided by elapsed time, converted to kilometres and miles per hour.',limits:'The estimate assumes a constant pace. Terrain, stops, weather and GPS distance error affect actual performance.',faq:'What is a 30-minute 5K pace? It is 6 minutes per kilometre, about 9 minutes 39 seconds per mile.'},
  { slug:'work-hours-calculator',title:'Work Hours and Timecard Calculator',description:'Calculate shift length and paid work hours from clock-in, clock-out and an unpaid break, including overnight shifts.',action:'Calculate work hours',fields:[['break','Unpaid break (minutes)','30',0,1440,'1']],textFields:[['start','Clock in (24-hour time)','09:00'],['end','Clock out (24-hour time)','17:30']],formula:'Elapsed shift time is the difference between clock-out and clock-in; when the end time is earlier, the shift is treated as crossing midnight. Paid time subtracts the unpaid break.',limits:'Enter local clock times in HH:MM. This calculates duration only; it does not determine overtime, payroll rounding or employment-law requirements.',faq:'How do I calculate hours worked overnight? If clock-out is earlier than clock-in, the calculator treats clock-out as the following day.'},
  { slug:'date-add-subtract-calculator',title:'Date Add or Subtract Calculator',description:'Find a date by adding or subtracting a chosen number of days, weeks, months or years from a starting date.',action:'Calculate new date',fields:[['amount','Amount','30',0,1000000,'1']],selects:[{key:'direction',label:'Operation',value:'add',options:[{value:'add',label:'Add'},{value:'subtract',label:'Subtract'}]},{key:'unit',label:'Date unit',value:'days',options:[{value:'days',label:'Days'},{value:'weeks',label:'Weeks'},{value:'months',label:'Months'},{value:'years',label:'Years'}]}],textFields:[['date','Starting date (UTC calendar date)','2026-11-08','date']],formula:'Days and weeks use calendar-day arithmetic. Month and year changes clamp to the last valid day in the destination month (for example, January 31 plus one month becomes the last day of February).',limits:'The tool treats the entered value as a calendar date without a time zone or daylight-saving time.',faq:'What date is 30 days from a date? Enter the starting date, choose Add and Days, then enter 30.'},
  { slug:'hourly-to-salary-calculator',title:'Hourly to Annual Salary Calculator',description:'Convert an hourly wage into estimated weekly, monthly and annual gross pay using work hours and paid weeks.',action:'Convert hourly pay',fields:[['rate','Hourly pay rate','25',0,1000000],['hours','Paid hours per week','40',0.1,168],['weeks','Paid weeks per year','52',0.1,53]],formula:'Annual gross pay = hourly rate × paid hours per week × paid weeks per year. Monthly equivalent divides annual pay by 12.',limits:'This is gross pay before taxes, benefits, overtime, unpaid leave and variable schedules.',faq:'How much is $25 an hour per year? At 40 hours per week for 52 paid weeks, gross annual pay is $52,000.'},
  { slug:'profit-margin-calculator',title:'Profit Margin and Markup Calculator',description:'Calculate gross profit, profit margin and markup from cost and selling price, or find a selling price for a target margin.',action:'Calculate margin and markup',fields:[['cost','Cost per item','40',0,1000000000],['price','Selling price','60',0,1000000000]],formula:'Gross profit = selling price − cost. Margin = profit ÷ selling price. Markup = profit ÷ cost.',limits:'This simple calculation excludes taxes, shipping, payment fees, overhead, returns and discounts. A margin percentage uses selling price as its denominator; markup uses cost.',faq:'What is the difference between profit margin and markup? Margin divides profit by selling price, while markup divides profit by cost.'},
  { slug:'break-even-calculator',title:'Break-Even Point Calculator',description:'Find the units and sales revenue needed to cover fixed costs using selling price and variable cost per unit.',action:'Calculate break-even point',fields:[['fixed','Fixed costs','5000',0,1000000000],['price','Selling price per unit','50',0.01,1000000000],['variable','Variable cost per unit','20',0,1000000000]],formula:'Contribution per unit = selling price − variable cost. Break-even units = fixed costs ÷ contribution per unit, rounded up.',limits:'Assumes constant prices and unit costs. It excludes taxes, financing, capacity limits, product mix and changes in costs at different sales volumes.',faq:'How many units do I need to sell to break even? Divide fixed costs by the contribution per unit and round up to a whole unit.'},
  { slug:'commission-calculator',title:'Sales Commission Calculator',description:'Calculate sales commission and total gross pay from sales, a commission rate and optional base pay.',action:'Calculate commission',fields:[['sales','Sales amount','10000',0,1000000000],['rate','Commission rate (%)','5',0,100],['base','Base pay for this period','0',0,1000000000]],formula:'Commission = eligible sales × commission rate. Estimated gross pay adds the entered base pay.',limits:'This is a flat-rate estimate. Tiers, quotas, returns, caps, chargebacks and employment agreements are not included.',faq:'How do you calculate a 5% sales commission? Multiply eligible sales by 0.05.'},
  { slug:'vat-calculator',title:'VAT Calculator',description:'Add VAT to a net price or extract VAT from a VAT-inclusive total using your entered rate.',action:'Calculate VAT',fields:[['amount','Amount','100',0,1000000000],['rate','VAT rate (%)','20',0,100]],select:{key:'mode',label:'Price entry',value:'net',options:[{value:'net',label:'Net price — add VAT'},{value:'gross',label:'Gross price — extract VAT'}]},formula:'For net prices, VAT = amount × rate. For gross prices, net = total ÷ (1 + rate), and VAT is the difference.',limits:'VAT rates, exemptions, invoice rules and rounding vary by country and product. Enter the applicable rate and confirm local requirements.',faq:'How do I remove VAT from a price? Divide the VAT-inclusive total by one plus the VAT rate as a decimal; subtract the net amount to find VAT.'},
  { slug:'unit-price-calculator',title:'Unit Price Comparison Calculator',description:'Compare the cost per kilogram, litre, item or other unit for two products to find the better value.',action:'Compare unit prices',fields:[['priceA','Product A price','4.50',0,1000000000],['quantityA','Product A quantity','500',0.001,1000000000],['priceB','Product B price','6.20',0,1000000000],['quantityB','Product B quantity','750',0.001,1000000000]],textFields:[['unit','Shared unit label','g']],formula:'Unit price = package price ÷ package quantity. The lower unit price is cheaper for the same quantity.',limits:'Enter both quantities in the same unit (for example, grams and grams). Promotions, quality and waste are not included.',faq:'How do I compare price per 100 grams? Divide each package price by its weight in grams, then multiply by 100.'},
  { slug:'recipe-cost-calculator',title:'Recipe Cost Per Serving Calculator',description:'Estimate total recipe cost and cost per serving from ingredient spend, servings and optional extra costs.',action:'Calculate recipe cost',fields:[['ingredients','Ingredient cost total','12',0,1000000000],['servings','Number of servings','6',1,1000000,'1'],['extras','Extra costs (%)','5',0,100]],formula:'Recipe cost = ingredient cost × (1 + extra-cost allowance). Cost per serving divides the result by servings.',limits:'Use your actual package purchase prices and the portion of each package used. This estimate excludes energy, labour, waste and changing ingredient prices unless you account for them.',faq:'How do I find recipe cost per serving? Add the cost of the quantities used for all ingredients and divide by the number of servings.'},
  { slug:'average-statistics-calculator',title:'Mean Median Mode and Range Calculator',description:'Find the mean, median, mode and range of a list of numbers for homework, reports and quick data checks.',action:'Calculate statistics',kind:'text',inputLabel:'Numbers (separate with commas, spaces or new lines)',fields:[],textFields:[],formula:'Mean is the arithmetic average; median is the middle sorted value; mode is the most frequent value; range is maximum minus minimum.',limits:'Paste numbers separated by spaces, commas or line breaks. The tool reports multiple modes when values tie for highest frequency.',faq:'How do I find the median? Sort the numbers; take the middle value, or average the two middle values when there is an even number of entries.'},
  { slug:'standard-deviation-calculator',title:'Standard Deviation Calculator',description:'Calculate population or sample standard deviation and variance from a list of values.',action:'Calculate standard deviation',kind:'text',inputLabel:'Numbers (separate with commas, spaces or new lines)',fields:[],textFields:[],select:{key:'mode',label:'Data type',value:'population',options:[{value:'population',label:'Entire population'},{value:'sample',label:'Sample'}]},formula:'Population variance divides squared deviations by N; sample variance divides by N − 1. Standard deviation is the square root of variance.',limits:'Use population mode when the values are the complete group of interest; use sample mode when they represent a sample used to estimate a larger group.',faq:'When should I use sample standard deviation? Use the sample formula with N − 1 when your values are a sample and you are estimating variation in a larger population.'},
  { slug:'percentage-point-calculator',title:'Percentage Point Change Calculator',description:'Calculate the percentage-point difference and relative percentage change between two rates.',action:'Compare percentages',fields:[['start','Starting rate (%)','12',-100000,100000],['end','Ending rate (%)','15',-100000,100000]],formula:'Percentage-point change = ending percentage − starting percentage. Relative percent change = difference ÷ absolute starting rate × 100.',limits:'Percentage points describe the direct difference between two rates. Relative percent change describes the size of that difference compared with the starting rate.',faq:'Is a rise from 12% to 15% a 3% increase? It is a 3 percentage-point increase and a 25% relative increase.'},
  { slug:'paper-size-converter',title:'Paper Size and Print Pixel Converter',description:'Convert common ISO A-series, US Letter and Legal paper sizes between millimetres, inches and print pixels.',action:'Convert paper size',fields:[['dpi','Print resolution (DPI)','300',1,2400,'1']],selects:[{key:'size',label:'Paper size',value:'a4',options:[{value:'a0',label:'A0'},{value:'a1',label:'A1'},{value:'a2',label:'A2'},{value:'a3',label:'A3'},{value:'a4',label:'A4'},{value:'a5',label:'A5'},{value:'letter',label:'US Letter'},{value:'legal',label:'US Legal'}]},{key:'orientation',label:'Orientation',value:'portrait',options:[{value:'portrait',label:'Portrait'},{value:'landscape',label:'Landscape'}]}],formula:'Physical dimensions use standard ISO 216 or US paper sizes. Pixel dimensions are calculated as inches × entered DPI and rounded to whole pixels.',limits:'Pixel dimensions depend on resolution. Printing software and printer margins may scale or clip the document.',faq:'What is A4 in pixels at 300 DPI? A4 is approximately 2480 × 3508 pixels at 300 DPI in portrait orientation.'},
  { slug:'payday-calendar-generator',title:'Payday Calendar Generator',description:'Generate upcoming weekly, biweekly or monthly payday dates from your next payday.',action:'Generate paydays',fields:[['count','Number of paydays','12',1,52,'1']],textFields:[['start','Next payday (YYYY-MM-DD)','2026-11-13','date']],select:{key:'frequency',label:'Pay frequency',value:'biweekly',options:[{value:'weekly',label:'Weekly'},{value:'biweekly',label:'Every two weeks'},{value:'monthly',label:'Monthly'}]},formula:'Weekly and biweekly schedules add 7 or 14 calendar days. Monthly dates retain the day when possible and clamp to the last valid day in shorter months.',limits:'This calendar does not adjust for bank holidays, employer changes, or early deposits. Confirm dates with your payroll provider.',faq:'How do I calculate biweekly paydays? Start with a confirmed payday and add 14 calendar days for each following payday.'},
  { slug:'sleep-cycle-calculator',title:'Sleep Cycle Bedtime Calculator',description:'Estimate bedtime or wake-up options using common 90-minute sleep-cycle intervals and time to fall asleep.',action:'Calculate sleep times',fields:[['latency','Time to fall asleep (minutes)','15',0,180,'1']],textFields:[['time','Wake-up time (HH:MM)','07:00']],select:{key:'cycles',label:'Sleep cycles',value:'5',options:[{value:'4',label:'4 cycles (about 6 hours)'},{value:'5',label:'5 cycles (about 7.5 hours)'},{value:'6',label:'6 cycles (about 9 hours)'}]},formula:'The estimate counts back 90 minutes per selected cycle and subtracts your expected time to fall asleep.',limits:'Sleep-cycle length varies between people and across the night. This is a scheduling aid, not a sleep or medical assessment; regular sufficient sleep matters more than matching an exact cycle.',faq:'What time should I go to bed to wake at 7 AM? For five estimated 90-minute cycles plus 15 minutes to fall asleep, the suggested time is 11:15 PM.'},
  { slug:'calorie-needs-calculator',title:'Daily Calorie Needs Estimator',description:'Estimate resting energy and daily maintenance calories for adults using age, height, weight and activity level.',action:'Estimate daily energy',fields:[['age','Age (years)','30',19,78,'1'],['weight','Weight (kg)','70',25,300],['height','Height (cm)','170',100,230]],selects:[{key:'sex',label:'Equation option',value:'female',options:[{value:'female',label:'Female equation'},{value:'male',label:'Male equation'}]},{key:'activity',label:'Activity estimate',value:'1.2',options:[{value:'1.2',label:'Low activity'},{value:'1.375',label:'Light activity'},{value:'1.55',label:'Moderate activity'},{value:'1.725',label:'High activity'},{value:'1.9',label:'Very high activity'}]}],formula:'Resting energy estimate uses the Mifflin–St Jeor predictive equation; estimated maintenance multiplies that result by the selected activity factor.',limits:'A population equation is not an individual measurement. Intended for adults in the age range studied; not for children, pregnancy, eating-disorder care or medical nutrition plans. Daily energy needs vary and a clinician or registered dietitian can provide individual guidance.',faq:'How are daily calorie needs estimated? The tool estimates resting energy from age, height, weight and equation option, then applies an activity multiplier. The result is approximate, not a prescribed intake.',reference:'https://pubmed.ncbi.nlm.nih.gov/2305711/'},
  {slug:'mortgage-payment-calculator',title:'Mortgage Payment Calculator',description:'Estimate monthly mortgage principal and interest, plus property tax, home insurance and HOA costs.',action:'Calculate monthly payment',fields:[['price','Home price','350000',1,1000000000],['down','Down payment','70000',0,1000000000],['rate','Annual interest rate (%)','6.5',0,100],['years','Loan term (years)','30',1,50,'1'],['tax','Monthly property tax','350',0,10000000],['insurance','Monthly home insurance','120',0,10000000],['hoa','Monthly HOA fee','0',0,10000000]],formula:'Monthly principal and interest use the standard fixed-rate amortizing loan formula. Property tax, insurance and HOA are added as entered.',limits:'Estimate only. It excludes PMI, closing costs, escrow changes, maintenance, and lender-specific fees. Tax and insurance vary by location; compare a lender quote before making a decision.',faq:'How do I estimate a monthly mortgage payment? Enter the financed amount, annual rate and term; the calculator estimates principal and interest, then adds the monthly costs you provide.'},
  {slug:'mortgage-affordability-calculator',title:'Mortgage Affordability Calculator',description:'Estimate a home price range from gross monthly income, monthly debts, a payment ratio and loan assumptions.',action:'Estimate home budget',fields:[['income','Gross monthly income','7000',1,100000000],['debts','Monthly debt payments','600',0,10000000],['housingRatio','Housing payment limit (%)','28',1,100],['debtRatio','Total debt limit (%)','36',1,100],['down','Available down payment','50000',0,100000000],['rate','Annual mortgage rate (%)','6.5',0,100],['years','Loan term (years)','30',1,50,'1']],formula:'The lower of the entered housing-payment limit and total-debt limit determines an estimated principal-and-interest budget; the standard loan formula estimates principal.',limits:'This simplified estimate uses gross income and excludes property taxes, insurance, HOA, PMI, closing costs and lender underwriting rules. The selected ratios are planning assumptions, not approval criteria.',faq:'How much house can I afford based on monthly income? Choose conservative payment ratios, subtract current debt obligations from the total-debt limit, and use the lower resulting payment to estimate a loan amount.'},
  {slug:'car-loan-payment-calculator',title:'Car Loan Payment Calculator',description:'Calculate an estimated auto loan payment from vehicle price, down payment, sales tax, interest rate and term.',action:'Calculate car payment',fields:[['price','Vehicle price','28000',0,10000000],['down','Down payment','5000',0,10000000],['trade','Trade-in value applied','0',0,10000000],['tax','Sales tax (%)','7',0,100],['rate','Annual interest rate (%)','6.9',0,100],['months','Loan term (months)','60',1,120,'1']],formula:'Financed amount = vehicle price × (1 + entered tax rate) − down payment − trade-in. A fixed-rate amortization formula estimates the monthly payment.',limits:'Registration, dealer fees, add-ons, rebates, negative equity, and changing rates are excluded. Use the actual amount financed and lender disclosure for a real offer.',faq:'How is a monthly car loan payment calculated? The price and tax are reduced by down payment and trade-in, then amortized over the selected term at the annual rate.'},
  {slug:'credit-card-payoff-calculator',title:'Credit Card Payoff Calculator',description:'Estimate how long a fixed monthly payment will take to clear a credit card balance and how much interest it may add.',action:'Estimate payoff time',fields:[['balance','Current card balance','4200',0.01,100000000],['apr','Annual percentage rate (%)','24.99',0,1000],['payment','Monthly payment','180',0.01,10000000]],formula:'The balance is reduced monthly after adding the monthly share of the entered APR. The estimate simulates payments until the balance reaches zero.',limits:'Assumes no new purchases, fees, rate changes or missed payments. Real card issuers may calculate interest daily and apply minimum-payment rules; check your statement.',faq:'How long will it take to pay off my credit card? Enter the balance, APR and fixed monthly payment; the estimate shows the number of months and interest under a simplified monthly model.'},
  {slug:'debt-to-income-calculator',title:'Debt-to-Income Ratio Calculator',description:'Calculate monthly debt-to-income ratio from gross income and recurring monthly debt obligations.',action:'Calculate DTI',fields:[['income','Gross monthly income','6000',0.01,100000000],['debt','Monthly debt payments','1500',0,100000000]],formula:'Debt-to-income ratio = recurring monthly debt payments ÷ gross monthly income × 100.',limits:'Lenders may count debts and income differently and use other underwriting criteria. This estimate does not predict approval or include all household expenses.',faq:'How do I calculate debt-to-income ratio? Add required monthly debt payments, divide by gross monthly income before tax, then multiply by 100.'},
  {slug:'rent-affordability-calculator',title:'Rent Affordability Calculator',description:'Estimate a monthly rent budget using gross income, recurring debt and a chosen housing-cost percentage.',action:'Estimate rent budget',fields:[['income','Gross monthly income','5000',1,100000000],['debt','Monthly debt payments','500',0,10000000],['ratio','Housing budget (% of income)','30',1,100]],formula:'Suggested rent budget = gross monthly income × selected housing percentage. A second figure subtracts entered monthly debt payments for a more cautious comparison.',limits:'This rule-of-thumb estimate excludes utilities, insurance, deposits, local rent standards, taxes, savings and other living costs. It is not an eligibility decision.',faq:'How much rent can I afford on my income? Pick a housing percentage that fits your expenses; compare the result with utilities, debts, savings and local costs.'},
  {slug:'emergency-fund-calculator',title:'Emergency Fund Calculator',description:'Set a savings target from essential monthly expenses, a chosen number of months and your current reserve.',action:'Calculate fund target',fields:[['expenses','Essential monthly expenses','2400',0,100000000],['months','Months of expenses','6',1,36,'1'],['current','Current emergency savings','3000',0,100000000]],formula:'Target = essential monthly expenses × selected months. Remaining amount = target minus current savings, with a minimum of zero.',limits:'The target is a planning choice, not a universal rule. Income stability, dependents, insurance and access to support can change the amount that fits your situation.',faq:'How much should I keep in an emergency fund? Choose a number of months that fits your circumstances and multiply it by essential monthly costs; subtract savings already set aside.'},
  {slug:'savings-with-contributions-calculator',title:'Savings Growth Calculator with Monthly Deposits',description:'Project savings growth with an initial balance, recurring monthly deposits, an annual rate and a time horizon.',action:'Project savings',fields:[['initial','Starting balance','1000',0,1000000000],['deposit','Monthly deposit','250',0,10000000],['rate','Annual interest rate (%)','4',0,100],['years','Years','5',0.1,100]],formula:'Projects end-of-month deposits with monthly compounding at the entered nominal annual rate; also totals deposits and estimated interest.',limits:'Assumes a constant rate, regular deposits, no fees, taxes, withdrawals or inflation. Actual savings rates can change; this is not an investment forecast.',faq:'How much can regular monthly savings grow? Enter a starting balance, monthly deposit, assumed annual rate and years to see a compound-growth estimate.'},
  {slug:'simple-interest-calculator',title:'Simple Interest Calculator',description:'Calculate simple interest and total value from principal, annual rate and time.',action:'Calculate simple interest',fields:[['principal','Starting principal','2500',0,1000000000000],['rate','Annual interest rate (%)','5',0,1000],['years','Time (years)','3',0,1000]],formula:'Simple interest = principal × annual rate × time. Total = principal + interest; compounding is not included.',limits:'Use the rate and time basis from your agreement. This estimate excludes fees, taxes, compounding and changing balances and is not a loan or investment quote.',faq:'What is the formula for simple interest? Multiply the principal by the annual rate as a decimal and by the number of years.'},
  {slug:'apr-to-apy-calculator',title:'APR to APY Calculator',description:'Convert a nominal annual percentage rate into an effective annual yield for a selected compounding frequency.',action:'Convert APR to APY',fields:[['apr','Nominal annual rate (%)','5',-100,1000],['periods','Compounding periods per year','12',1,365,'1']],formula:'APY = (1 + APR ÷ compounding periods) raised to compounding periods, minus one.',limits:'This mathematical conversion excludes fees and assumes the same nominal rate for the full year. APR conventions can differ for lending products; use the issuer’s disclosed terms.',faq:'How do I convert APR to APY? Divide the nominal annual rate by the number of compounding periods, compound for one year, and express the result as a percentage.'},
  {slug:'average-speed-calculator',title:'Average Speed Calculator',description:'Calculate average speed from distance and travel time in kilometres per hour and miles per hour.',action:'Calculate average speed',fields:[['distance','Distance (km)','120',0.001,1000000000],['hours','Hours','1',0,100000],['minutes','Minutes','30',0,59,'1']],formula:'Average speed = distance divided by total elapsed time. The result is also converted to miles per hour.',limits:'This is an overall average, including any stops represented in the entered time. It is not a recommended or safe driving speed.',faq:'How do I calculate average speed? Divide the total distance by total elapsed time, making sure distance and time units are compatible.'},
  {slug:'fuel-range-calculator',title:'Fuel Range Calculator',description:'Estimate driving distance from usable fuel volume and your vehicle’s fuel consumption.',action:'Estimate driving range',fields:[['fuel','Usable fuel (litres)','45',0.01,100000],['consumption','Fuel consumption (L/100 km)','7.2',0.01,1000]],formula:'Estimated range = usable litres ÷ consumption in litres per 100 km × 100.',limits:'Real range varies with speed, traffic, load, weather, terrain and vehicle condition. Keep a fuel reserve; do not treat the estimate as a guarantee.',faq:'How far can I drive with a certain amount of fuel? Divide litres available by litres used per 100 km and multiply by 100.'},
  {slug:'trip-fuel-cost-calculator',title:'Trip Fuel Cost Calculator',description:'Estimate fuel needed and cost for a trip using distance, fuel consumption and price per litre.',action:'Estimate trip fuel cost',fields:[['distance','Trip distance (km)','320',0.01,1000000000],['consumption','Vehicle use (L/100 km)','7.5',0.01,1000],['price','Fuel price per litre','1.65',0,100000],['people','People splitting the cost','2',1,1000,'1']],formula:'Fuel needed = distance × consumption ÷ 100. Estimated total cost = litres × price; per-person cost divides by the entered number of people.',limits:'Uses one-way distance and the stated average consumption and price. Add a return journey or detour to the distance; actual consumption and pump prices can change.',faq:'How much will fuel cost for a trip? Multiply trip kilometres by litres per 100 km, divide by 100, then multiply the litres by the price per litre.'},
  {slug:'freelance-hourly-rate-calculator',title:'Freelance Hourly Rate Calculator',description:'Estimate a billable hourly rate from an annual income goal, business costs and realistic billable hours.',action:'Estimate hourly rate',fields:[['income','Annual income goal before personal tax','70000',0,100000000],['expenses','Annual business expenses','12000',0,100000000],['hours','Billable hours per week','20',0.1,168],['weeks','Billable weeks per year','46',1,53]],formula:'Estimated rate = (annual income goal + annual business expenses) ÷ (billable hours per week × billable weeks).',limits:'This estimate does not calculate personal taxes, benefits, unpaid leave, bad debt or market pricing. Billable capacity is often lower than total working hours; include realistic non-billable time.',faq:'How do I calculate a freelance hourly rate? Add the income you need and business costs, then divide by realistic annual billable hours.'},
  {slug:'prorated-rent-calculator',title:'Prorated Rent Calculator',description:'Calculate a partial-month rent amount from the monthly rent, days in that month and days charged.',action:'Calculate prorated rent',fields:[['rent','Monthly rent','1500',0,100000000],['daysInMonth','Days in the month','30',28,31,'1'],['daysCharged','Days charged','12',0,31,'1']],formula:'Daily rent = monthly rent ÷ days in month. Prorated amount = daily rent × days charged.',limits:'Lease agreements and local rules may use different proration conventions or move-in day treatment. Confirm the method with the landlord or lease before paying.',faq:'How do I prorate rent for part of a month? Divide monthly rent by the number of days in the month, then multiply by the days charged under your agreement.'},
  {slug:'test-score-calculator',title:'Test Score Percentage Calculator',description:'Calculate a test percentage, points missed and points needed to reach a target score.',action:'Calculate test score',fields:[['earned','Points earned','42',0,1000000000],['possible','Total possible points','50',0.01,1000000000],['target','Target percentage (%)','90',0,100]],formula:'Score percentage = points earned ÷ total possible points × 100. Points needed for a target = target percentage × total points.',limits:'The calculator does not assign letter grades because grading scales vary by school and course. Weighted questions and extra credit must be reflected in the point totals you enter.',faq:'How do I calculate my test percentage? Divide points earned by total points possible and multiply by 100.'},
  {slug:'attendance-percentage-calculator',title:'Attendance Percentage Calculator',description:'Find your current attendance rate and estimate how many future sessions you can miss while meeting a target.',action:'Calculate attendance',fields:[['attended','Sessions attended','18',0,1000000,'1'],['held','Sessions held so far','20',1,1000000,'1'],['future','Sessions remaining','10',0,1000000,'1'],['target','Required attendance (%)','80',0,100]],formula:'Current rate = attended ÷ sessions held × 100. Maximum future absences = total sessions minus minimum whole sessions needed for the target, less absences already taken.',limits:'Institutions may round percentages or count excused absences differently. Confirm the official attendance policy; this estimate uses whole sessions and a single threshold.',faq:'How many classes can I miss and keep 80% attendance? Apply the required percentage to all sessions in the term, round the required attended sessions up, then subtract sessions already missed.'},
  {slug:'percentage-error-calculator',title:'Percentage Error Calculator',description:'Compare an observed value with a reference value and calculate absolute error and relative percentage error.',action:'Calculate percentage error',fields:[['reference','Reference value','100',-1000000000,1000000000],['observed','Observed value','96.5',-1000000000,1000000000]],formula:'Absolute error = |observed − reference|. Relative percentage error = absolute error ÷ |reference| × 100 when the reference is nonzero.',limits:'Percentage error is undefined when the reference value is zero. Match units and sign conventions before comparing measurements.',faq:'How do I calculate percentage error? Subtract the reference from the observed value, take the absolute difference, divide by the absolute reference and multiply by 100.'},
  {slug:'inflation-adjusted-value-calculator',title:'Inflation Adjusted Value Calculator',description:'Estimate future cost or the future equivalent of today’s amount using an assumed annual inflation rate.',action:'Calculate inflation adjustment',fields:[['amount','Amount in today’s money','1000',0,1000000000000],['rate','Assumed annual inflation (%)','3',-99,1000],['years','Number of years','10',0,1000]],formula:'Future equivalent = current amount × (1 + annual inflation rate) raised to the number of years. Purchasing-power equivalent divides by the same factor.',limits:'Uses a constant assumed rate, while actual inflation varies by time, region and spending category. This is an illustrative calculation, not an economic forecast.',faq:'How much will today’s money be worth after inflation? Apply the assumed annual rate over the chosen years; use the reverse calculation to express a future amount in today’s purchasing power.'},
  {slug:'loan-amortization-calculator',title:'Loan Amortization Calculator',description:'Estimate a fixed-rate loan payment, total interest and payoff time when you add an extra monthly amount.',action:'Calculate loan payoff',fields:[['principal','Loan balance','20000',0.01,1000000000],['rate','Annual interest rate (%)','7',0,1000],['years','Original term (years)','5',0.1,100],['extra','Extra monthly payment','50',0,10000000]],formula:'The base payment uses a fixed-rate amortization formula. The calculator simulates monthly interest and payments with the extra amount until the balance is paid.',limits:'Assumes a fixed rate, monthly payments, no fees, and no prepayment penalties. Actual lender methods and payment dates can differ; confirm terms before changing payments.',faq:'Does paying extra reduce loan interest? For a standard amortizing loan, extra principal payments can shorten payoff and reduce interest, subject to lender rules and fees.'},
  {slug:'conversion-rate-calculator',title:'Conversion Rate Calculator',description:'Calculate website or campaign conversion rate from visitors and completed goals.',action:'Calculate conversion rate',fields:[['visitors','Visitors or sessions','2500',0,1000000000000],['conversions','Completed conversions','125',0,1000000000000]],formula:'Conversion rate = completed conversions ÷ visitors or sessions × 100.',limits:'Use a consistent denominator such as sessions or unique visitors. Analytics tools may define and deduplicate these differently; this calculator does not assess attribution.',faq:'How do I calculate conversion rate? Divide completed goals by the selected visitor or session count and multiply by 100.'},
  {slug:'cost-per-acquisition-calculator',title:'Cost Per Acquisition Calculator',description:'Find average advertising cost per new customer, signup or other acquisition goal.',action:'Calculate acquisition cost',fields:[['spend','Campaign spend','1200',0,1000000000],['acquisitions','New customers or leads','48',0,1000000000]],formula:'Cost per acquisition = total campaign spend ÷ attributed acquisitions.',limits:'Use acquisitions measured over the same campaign period and attribution method as spend. This simple average excludes lifetime value, organic conversions and other costs.',faq:'How do I calculate cost per acquisition? Divide advertising spend by the number of acquisitions attributed to that spend.'},
  {slug:'return-on-ad-spend-calculator',title:'ROAS Calculator',description:'Calculate return on ad spend from attributed revenue and advertising cost.',action:'Calculate ROAS',fields:[['revenue','Attributed revenue','8400',0,1000000000],['spend','Advertising spend','1600',0,1000000000]],formula:'ROAS = attributed revenue ÷ advertising spend. Revenue-to-spend percentage is ROAS × 100.',limits:'ROAS is a revenue ratio, not profit. It excludes product cost, refunds, taxes, agency fees and attribution uncertainty.',faq:'How do I calculate ROAS? Divide revenue attributed to ads by the ad spend; a result of 4 means four units of revenue per unit spent.'},
  {slug:'click-through-rate-calculator',title:'Click Through Rate Calculator',description:'Calculate ad, email or search result click-through rate from clicks and impressions.',action:'Calculate click-through rate',fields:[['clicks','Clicks','240',0,1000000000000],['impressions','Impressions','12000',0.01,1000000000000]],formula:'Click-through rate = clicks ÷ impressions × 100.',limits:'Platforms define impressions, viewability and invalid-click filtering differently. Compare rates from the same platform and reporting setup.',faq:'How do I calculate click-through rate? Divide the number of clicks by the number of impressions and multiply by 100.'},
  {slug:'email-campaign-metrics-calculator',title:'Email Campaign Metrics Calculator',description:'Calculate delivered-email open, click and unsubscribe rates from one campaign’s aggregate counts.',action:'Calculate email metrics',fields:[['delivered','Emails delivered','9500',0.01,1000000000000],['opens','Unique opens','2750',0,1000000000000],['clicks','Unique clicks','620',0,1000000000000],['unsubscribes','Unsubscribes','19',0,1000000000000]],formula:'Open, click and unsubscribe rates divide each event count by delivered emails. Click-to-open rate divides unique clicks by unique opens.',limits:'Mail privacy features, bot filtering and provider definitions affect these rates. Use aggregate counts from the same campaign and reporting window; do not treat opens as confirmed human reads.',faq:'How do I calculate an email open rate? Divide unique opens by delivered emails and multiply by 100.'},
  {slug:'net-worth-calculator',title:'Net Worth Calculator',description:'Estimate personal net worth by totaling assets and subtracting debts and other liabilities.',action:'Calculate net worth',fields:[['cash','Cash and savings','8000',0,1000000000000],['investments','Investments and retirement accounts','24000',0,1000000000000],['property','Property value','220000',0,1000000000000],['otherAssets','Other assets','6000',0,1000000000000],['mortgage','Mortgage balance','165000',0,1000000000000],['loans','Other loan balances','12000',0,1000000000000],['cards','Credit card balances','2300',0,1000000000000],['otherDebts','Other liabilities','0',0,1000000000000]],formula:'Net worth = total estimated asset values − total outstanding liabilities.',limits:'Use current approximate values and balances. This snapshot is not a valuation, credit assessment, tax calculation or financial recommendation.',faq:'How do I calculate net worth? Add the current value of assets you own and subtract the outstanding balances of debts and other liabilities.'},
  {slug:'monthly-budget-calculator',title:'Monthly Budget Calculator',description:'Compare take-home income with common monthly spending categories and a savings goal.',action:'Calculate monthly budget',fields:[['income','Monthly take-home income','4200',0,1000000000],['housing','Housing and utilities','1450',0,1000000000],['bills','Other recurring bills','380',0,1000000000],['food','Food and household shopping','520',0,1000000000],['transport','Transport','260',0,1000000000],['debt','Debt payments','240',0,1000000000],['savings','Planned savings','500',0,1000000000]],formula:'Remaining amount = take-home income − entered expenses and planned savings. Category share = category amount ÷ income × 100.',limits:'Enter net income and avoid counting a bill in multiple categories. Irregular costs and annual expenses should be converted to monthly amounts if you want them included.',faq:'How do I make a monthly budget? Compare take-home income with recurring bills, variable spending, debt payments and a savings target; the remainder shows what is unassigned.'},
  {slug:'wedding-budget-calculator',title:'Wedding Budget Calculator',description:'Add major wedding costs and a per-guest catering estimate to see the total and remaining budget.',action:'Estimate wedding budget',fields:[['budget','Total budget','18000',0,1000000000],['guests','Guest count','80',0,10000,'1'],['venue','Venue and rentals','4500',0,1000000000],['catering','Catering per guest','85',0,1000000],['attire','Attire','1800',0,1000000000],['photo','Photography and video','2400',0,1000000000],['decor','Flowers and decor','1200',0,1000000000],['music','Music and entertainment','900',0,1000000000],['other','Other estimated costs','1500',0,1000000000]],formula:'Estimated total = fixed category costs + guest count × catering per guest. Remaining budget = entered budget − estimated total.',limits:'Estimates depend on location, taxes, service fees, gratuities and supplier contracts. Add missing categories and confirm written quotes before committing.',faq:'How do I estimate a wedding budget? Add fixed costs and multiply per-guest costs by the guest count, then compare the total with your budget.'},
  {slug:'moving-cost-calculator',title:'Moving Cost Calculator',description:'Estimate moving expenses from truck, movers, packing, travel and other costs, with an optional contingency.',action:'Estimate moving costs',fields:[['truck','Truck or container','450',0,100000000],['movers','Moving labor','900',0,100000000],['packing','Packing supplies','180',0,100000000],['travel','Travel and fuel','160',0,100000000],['storage','Storage','0',0,100000000],['cleaning','Cleaning and setup','220',0,100000000],['other','Other costs','150',0,100000000],['contingency','Contingency allowance (%)','10',0,100]],formula:'Base cost = entered line items. Estimated total adds the selected contingency percentage to that subtotal.',limits:'Quotes may exclude stairs, long carries, insurance, deposits, taxes or schedule changes. Check provider terms and replace estimates with confirmed prices.',faq:'How do I estimate moving costs? Add the truck, labor, packing, travel, storage and setup costs, then add an allowance for items that may change.'},
  {slug:'trip-budget-calculator',title:'Trip Budget Calculator',description:'Estimate a trip budget from travel costs, daily lodging, meals, activities and a contingency.',action:'Estimate trip budget',fields:[['days','Trip days','5',1,365,'1'],['people','Travelers','2',1,100,'1'],['transport','Transport total','600',0,1000000000],['lodging','Lodging per night','140',0,1000000000],['food','Food per person per day','55',0,1000000],['activities','Activities per person per day','30',0,1000000],['local','Local transport per day','18',0,1000000],['contingency','Contingency (%)','10',0,100]],formula:'Estimated base = transport + lodging × nights + per-person daily costs × people × days. Contingency is added as a percentage of the base.',limits:'Uses entered estimates only. It excludes exchange-rate changes, booking fees, insurance and visa costs; use current supplier quotes for planning.',faq:'How do I estimate a travel budget? Add transport and lodging to daily food, activity and local travel costs multiplied by travelers and days.'},
];

function fieldsFor(spec: ToolSpec): GrowthField[] {
  const numeric: GrowthField[] = spec.fields.map(([key, label, value, min = 0, max = 1000000000, step = 'any']) => ({ key, label, default: value, type: 'number', min, max, step }));
  for (const [key,label,value,type] of spec.textFields??[]) numeric.push({key,label,default:value,type:type??'text'});
  if (spec.select) numeric.push({ key: spec.select.key, label: spec.select.label, default: spec.select.value, type: 'select', options: spec.select.options });
  for (const select of spec.selects??[]) numeric.push({key:select.key,label:select.label,default:select.value,type:'select',options:select.options});
  return numeric;
}

